import{_ as t,o as e,c as s,a5 as c}from"./chunks/framework.a5no_H3L.js";const m=JSON.parse('{"title":"EF Core 迁移：让表结构随代码演进","description":"本页说明如何用迁移（migration）管理数据库结构变更，让表结构与实体模型保持一致。前置：已建立 DbContext 和实体（见EF Core）。读完你能安全地新增、应用和回退数据库结构变更。","frontmatter":{"type":"howto","level":"intermediate"},"headers":[],"relativePath":"csharp/06-data-access/chapter-04-migrations.md","filePath":"csharp/06-data-access/chapter-04-migrations.md"}'),r={name:"csharp/06-data-access/chapter-04-migrations.md"};function i(d,a,n,o,l,p){return e(),s("div",null,[...a[0]||(a[0]=[c('<h1 id="ef-core-迁移-让表结构随代码演进" tabindex="-1" data-src-line="2" data-src-file="csharp/06-data-access/chapter-04-migrations.md">EF Core 迁移：让表结构随代码演进 <a class="header-anchor" href="#ef-core-迁移-让表结构随代码演进" aria-label="Permalink to &quot;EF Core 迁移：让表结构随代码演进&quot;">​</a></h1><p data-src-line="4" data-src-file="csharp/06-data-access/chapter-04-migrations.md">本页说明如何用迁移（migration）管理数据库结构变更，让表结构与实体模型保持一致。前置：已建立 <code>DbContext</code> 和实体（见<a href="./chapter-02-ef-core.html">EF Core</a>）。读完你能安全地新增、应用和回退数据库结构变更。</p><h2 id="_1-迁移解决什么" tabindex="-1" data-src-line="6" data-src-file="csharp/06-data-access/chapter-04-migrations.md">1. 迁移解决什么 <a class="header-anchor" href="#_1-迁移解决什么" aria-label="Permalink to &quot;1. 迁移解决什么&quot;">​</a></h2><p data-src-line="8" data-src-file="csharp/06-data-access/chapter-04-migrations.md">实体模型会变：加字段、改类型、加表。迁移把这些结构变更写成可版本化、可回放的代码，使数据库结构随代码演进，而不是手工改表。</p><p data-src-line="10" data-src-file="csharp/06-data-access/chapter-04-migrations.md">迁移的核心产物是一系列带时间戳的迁移文件，记录「从上一版结构到这一版结构」的变更。团队通过提交这些文件，保证每个人的数据库结构一致。</p><h2 id="_2-创建迁移" tabindex="-1" data-src-line="12" data-src-file="csharp/06-data-access/chapter-04-migrations.md">2. 创建迁移 <a class="header-anchor" href="#_2-创建迁移" aria-label="Permalink to &quot;2. 创建迁移&quot;">​</a></h2><p data-src-line="14" data-src-file="csharp/06-data-access/chapter-04-migrations.md">安装工具后，用 <code>dotnet ef</code> 命令创建迁移：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dotnet ef migrations add AddBlogCategory</span></span></code></pre></div><p data-src-line="20" data-src-file="csharp/06-data-access/chapter-04-migrations.md">这条命令对比当前模型与上次迁移的模型，生成 <code>AddBlogCategory</code> 迁移文件，包含 <code>Up</code>（应用变更）和 <code>Down</code>（回退变更）两个方法。生成后先检查迁移内容，确认只包含预期的变更，再提交。</p><h2 id="_3-应用迁移" tabindex="-1" data-src-line="22" data-src-file="csharp/06-data-access/chapter-04-migrations.md">3. 应用迁移 <a class="header-anchor" href="#_3-应用迁移" aria-label="Permalink to &quot;3. 应用迁移&quot;">​</a></h2><p data-src-line="24" data-src-file="csharp/06-data-access/chapter-04-migrations.md">把迁移应用到数据库：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dotnet ef database update</span></span></code></pre></div><p data-src-line="30" data-src-file="csharp/06-data-access/chapter-04-migrations.md">开发时直接更新本地库。生产环境通常不运行此命令，而是生成 SQL 脚本由 DBA 审阅执行：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dotnet ef migrations script --idempotent -o migration.sql</span></span></code></pre></div><p data-src-line="36" data-src-file="csharp/06-data-access/chapter-04-migrations.md">生成幂等 SQL 脚本，便于在受控环境中审查和部署。生产数据库结构变更应走脚本评审流程，而不是应用启动时自动迁移。</p><h2 id="_4-迁移与版本控制" tabindex="-1" data-src-line="38" data-src-file="csharp/06-data-access/chapter-04-migrations.md">4. 迁移与版本控制 <a class="header-anchor" href="#_4-迁移与版本控制" aria-label="Permalink to &quot;4. 迁移与版本控制&quot;">​</a></h2><p data-src-line="40" data-src-file="csharp/06-data-access/chapter-04-migrations.md">迁移文件应纳入版本控制，与实体模型变更一起提交。这样：</p><ul data-src-line="42" data-src-file="csharp/06-data-access/chapter-04-migrations.md"><li data-src-line="42" data-src-file="csharp/06-data-access/chapter-04-migrations.md">回退代码时，能同时回退到对应的迁移。</li><li data-src-line="43" data-src-file="csharp/06-data-access/chapter-04-migrations.md">多人协作时，迁移按时间顺序排列，合并冲突显式可见。</li></ul><p data-src-line="45" data-src-file="csharp/06-data-access/chapter-04-migrations.md">迁移的顺序敏感：合并分支时若两个迁移基于同一父迁移，会冲突，需要手动解决顺序。</p><h2 id="_5-回退与删除" tabindex="-1" data-src-line="47" data-src-file="csharp/06-data-access/chapter-04-migrations.md">5. 回退与删除 <a class="header-anchor" href="#_5-回退与删除" aria-label="Permalink to &quot;5. 回退与删除&quot;">​</a></h2><p data-src-line="49" data-src-file="csharp/06-data-access/chapter-04-migrations.md">回退一个迁移：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dotnet ef database update PreviousMigration</span></span></code></pre></div><p data-src-line="55" data-src-file="csharp/06-data-access/chapter-04-migrations.md">删除尚未应用的最后一个迁移文件：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dotnet ef migrations remove</span></span></code></pre></div><p data-src-line="61" data-src-file="csharp/06-data-access/chapter-04-migrations.md">回退要谨慎：<code>Down</code> 方法可能删除数据（如 <code>DropColumn</code>），执行前确认没有不可逆的数据丢失。</p><h2 id="_6-失败信号与回退" tabindex="-1" data-src-line="63" data-src-file="csharp/06-data-access/chapter-04-migrations.md">6. 失败信号与回退 <a class="header-anchor" href="#_6-失败信号与回退" aria-label="Permalink to &quot;6. 失败信号与回退&quot;">​</a></h2><p data-src-line="65" data-src-file="csharp/06-data-access/chapter-04-migrations.md">应用迁移可能失败，常见信号：</p><ul data-src-line="67" data-src-file="csharp/06-data-access/chapter-04-migrations.md"><li data-src-line="67" data-src-file="csharp/06-data-access/chapter-04-migrations.md"><strong>迁移已部分应用</strong>：数据库有部分变更，但迁移记录未更新。此时数据库处于不一致状态，需人工核对实际结构。</li><li data-src-line="68" data-src-file="csharp/06-data-access/chapter-04-migrations.md"><strong>锁等待/超时</strong>：迁移的表被并发会话占用，重试或选择低峰期执行。</li><li data-src-line="69" data-src-file="csharp/06-data-access/chapter-04-migrations.md"><strong>数据不兼容</strong>：改字段类型但现有数据无法转换（如字符串转数字），需先清洗数据再迁移。</li></ul><p data-src-line="71" data-src-file="csharp/06-data-access/chapter-04-migrations.md">失败后先确认数据库实际状态，再决定重试还是回退，不要盲目重复执行迁移命令。</p><h2 id="_7-后续阅读" tabindex="-1" data-src-line="73" data-src-file="csharp/06-data-access/chapter-04-migrations.md">7. 后续阅读 <a class="header-anchor" href="#_7-后续阅读" aria-label="Permalink to &quot;7. 后续阅读&quot;">​</a></h2><ul data-src-line="75" data-src-file="csharp/06-data-access/chapter-04-migrations.md"><li data-src-line="75" data-src-file="csharp/06-data-access/chapter-04-migrations.md"><a href="./chapter-02-ef-core.html">EF Core</a>解释迁移所依据的模型与上下文。</li><li data-src-line="76" data-src-file="csharp/06-data-access/chapter-04-migrations.md"><a href="./chapter-03-query-tuning.html">查询与调优</a>解释结构变更对查询的影响。</li><li data-src-line="77" data-src-file="csharp/06-data-access/chapter-04-migrations.md"><a href="./chapter-05-testing.html">测试</a>解释如何用测试库验证迁移。</li></ul><blockquote data-src-line="79" data-src-file="csharp/06-data-access/chapter-04-migrations.md"><p data-src-line="79" data-src-file="csharp/06-data-access/chapter-04-migrations.md">本页的技术边界按 .NET 10 / C# 14 核对；<code>dotnet ef</code> 工具通过 <code>dotnet tool install --global dotnet-ef</code> 安装。官方参考：<a href="https://learn.microsoft.com/en-us/ef/core/managing-schemas/migrations/" target="_blank" rel="noreferrer">EF Core 迁移</a>。</p></blockquote>',32)])])}const g=t(r,[["render",i]]);export{m as __pageData,g as default};
